INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l13','as much as','',NULL,'/æz mʌtʃ æz/','It goes down as much as 25,000 feet.','它深达两万五千英尺。','He earns as much as I do.','他挣得和我一样多。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l13','by means of','',NULL,'/baɪ miːnz əv/','They control it by means of heavy mud.','他们靠沉重的泥浆来控制它。','We travel by means of trains.','我们靠火车出行。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l13','lead off','',NULL,'/liːd ɔːf/','The oil is led off safely.','石油被安全地引走。','A path leads off to the woods.','一条小路岔向树林。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l13','break into','',NULL,'/breɪk ˈɪntə/','Once the bit breaks into the oil, it flows up.','钻头一钻进油层,油就涌上来。','Thieves broke into the shop.','窃贼闯入了那家店。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp1','choice','{"stem":"\"Oil wells are the ___ holes of all that miners drill.\"(最高级,‘最深的’;deep 的最高级)","options":["deep","more deep","deepest","deeper"],"answer_index":2,"stem_cn":"油井是矿工所钻的所有孔中最深的。","explanation_cn":"最高级 the deepest,‘最深的’;deep 的最高级 deepest。✓ the deepest holes of all. ✗ deeper(比较级)/ deep(原级)/ more deep:单音节用 -est。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp1','choice','{"stem":"\"Some reach down as ___ as 25,000 feet.\"(‘多达…之多’as … as 结构,填中间的词)","options":["much","most","more","many"],"answer_index":0,"stem_cn":"有的深达两万五千英尺。","explanation_cn":"‘多达…之多’固定结构 as much as + 数量;中间的词是 much。✓ as much as 25,000 feet. ✗ many(不可数用 much)/ more / most:此结构中间用 much。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp1','choice','{"stem":"\"The search for oil improved deep drilling ___ than any other mining.\"(比较级,‘胜过任何其他’,填表示程度的比较级词)","options":["most","very","more","much"],"answer_index":2,"stem_cn":"探油对深钻的改进胜过任何其他采矿。","explanation_cn":"比较级 + than,‘胜过任何其他’;此处用 more。✓ improved deep drilling more than any other mining. ✗ most(最高级)/ much / very:与 than 搭配用比较级 more。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp2','choice','{"stem":"\"A tall derrick ___ raised above the drilling spot.\"(一般现在被动,填 be 动词)","options":["been","is","being","are"],"answer_index":1,"stem_cn":"一座高高的井架被竖立在钻探地点上方。","explanation_cn":"一般现在被动 is + 过去分词;主语 derrick 单数用 is。✓ A tall derrick is raised. ✗ are(复数)/ being / been:单数被动用 is + 过去分词。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp2','choice','{"stem":"\"Great lengths of pipe ___ lowered into the ground.\"(一般现在被动,主语复数,填 be 动词)","options":["is","was","being","are"],"answer_index":3,"stem_cn":"一根根长长的钻管被放入地下。","explanation_cn":"一般现在被动;主语 lengths of pipe 复数用 are。✓ Great lengths of pipe are lowered. ✗ is(单数)/ was(时态)/ being:复数被动用 are。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp2','choice','{"stem":"\"The pipe is ___ by a powerful engine at the top.\"(被动,‘被旋转’;rotate 的过去分词)","options":["rotating","to rotate","rotated","rotate"],"answer_index":2,"stem_cn":"钻管由顶部一台大功率发动机带动旋转。","explanation_cn":"被动 is + 过去分词;rotate 的过去分词 rotated。✓ The pipe is rotated by an engine. ✗ rotating(主动)/ rotate / to rotate:被动用过去分词 rotated。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp3','choice','{"stem":"\"___ the geologists have decided where to drill, work begins.\"(‘一旦/一…就’,填连词)","options":["Whether","Unless","Although","Once"],"answer_index":3,"stem_cn":"地质学家一决定在哪钻,工作就开始。","explanation_cn":"‘一旦/一…就’引导时间从句,用 Once。✓ Once the geologists have decided…, work begins. ✗ Unless / Although / Whether:表‘一…就’用 Once。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp3','choice','{"stem":"\"___ the bit breaks into the oil, it rushes to the surface.\"(‘一…就’,填连词)","options":["Before","Though","Once","Since"],"answer_index":2,"stem_cn":"钻头一钻到油层,油就涌向地面。","explanation_cn":"‘一…就’引导时间从句,用 Once。✓ Once the bit breaks into the oil, it rushes up. ✗ Since / Though / Before:表‘一…就’用 Once。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp3','choice','{"stem":"\"The oil flows up ___ the drill reaches it.\"(‘一…就/当…时’,填连词)","options":["once","although","unless","whereas"],"answer_index":0,"stem_cn":"钻头一触到油,油便涌出。","explanation_cn":"‘一…就/当…时’引导时间从句,用 once。✓ The oil flows up once the drill reaches it. ✗ unless / although / whereas:表‘一…就’用 once。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp4','choice','{"stem":"\"The core cuts a cylinder ___ which the strata can be read.\"(介词+关系代词,‘从其中’,填介词)","options":["at","for","on","from"],"answer_index":3,"stem_cn":"取芯钻头切出一段岩柱,从中可读出地层。","explanation_cn":"介词 + 关系代词:from which,‘从其中(读出)’;搭配 read from。✓ a cylinder from which the strata can be read. ✗ on / at / for:表‘从其中’用 from。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp4','choice','{"stem":"\"The mud ___ which they control the pressure is heavy.\"(介词+关系代词,‘借以…’means-of 结构,填开头的介词)","options":["of","by","at","from"],"answer_index":1,"stem_cn":"他们借以控制压力的泥浆很重。","explanation_cn":"介词 + 关系代词:by means of which,‘借以…’;开头的介词是 by。✓ the mud by means of which they control the pressure. ✗ from / at / of:此结构开头用 by。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp4','choice','{"stem":"\"The controlled manner ___ which the oil is led off is safe.\"(介词+关系代词,‘以…方式’,填介词)","options":["at","of","in","from"],"answer_index":2,"stem_cn":"油被引出所采用的那种可控方式很安全。","explanation_cn":"介词 + 关系代词:in which,‘以…方式(的)’;manner 搭配 in。✓ the manner in which the oil is led off. ✗ from / at / of:表‘以…方式’用 in。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp5','choice','{"stem":"\"Engineers want the oil ___ down the hole until led off safely.\"(want sb/sth 后接不定式,填正确形式)","options":["stayed","to stay","staying","stay"],"answer_index":1,"stem_cn":"工程师希望油留在井里,直到安全引出。","explanation_cn":"want sb/sth to do:want 后接不定式。✓ Engineers want the oil to stay down the hole. ✗ stay / staying / stayed:want 后用不定式 to stay。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp5','choice','{"stem":"\"They keep it down ___ they can lead it off safely.\"(‘直到…才’,填连词)","options":["until","since","whether","although"],"answer_index":0,"stem_cn":"他们把油封在下面,直到能安全引出。","explanation_cn":"‘直到…才’引导时间从句,用 until。✓ keep it down until they can lead it off. ✗ since / although / whether:表‘直到’用 until。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp5','choice','{"stem":"\"Nobody wants the gusher ___ oil into the air.\"(want sth 后接不定式,‘喷出’,填正确形式)","options":["thrown","to throw","throwing","throw"],"answer_index":1,"stem_cn":"没人想要那种把油喷向空中的井喷。","explanation_cn":"want sth to do:want 后接不定式。✓ Nobody wants the gusher to throw oil into the air. ✗ throw / throwing / thrown:want 后用不定式 to throw。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp6','choice','{"stem":"\"A tall tower built over an oil well is a ___.\"(“井架”用哪个词)","options":["bridge","fence","derrick","ladder"],"answer_index":2,"stem_cn":"立在油井上方的高塔。","explanation_cn":"立在油井上方的高塔是 derrick(井架)。✓ a tall tower over an oil well is a derrick. ✗ ladder 梯子;✗ bridge 桥;✗ fence 栅栏——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp6','choice','{"stem":"\"Layers of rock laid down over ages are ___.\"(“地层、岩层”复数用哪个词)","options":["strata","clouds","roots","rivers"],"answer_index":0,"stem_cn":"历经岁月沉积成的一层层岩石。","explanation_cn":"历经岁月沉积成的一层层岩石是 strata(地层,stratum 的复数)。✓ layers of rock are strata. ✗ rivers 河流;✗ clouds 云;✗ roots 根——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',5,'am4_l13_gp6','choice','{"stem":"\"A well that lets oil spout wildly into the air is a ___.\"(“井喷、喷油井”用哪个词)","options":["puddle","fountain","gusher","drain"],"answer_index":2,"stem_cn":"让油狂喷向空中的井。","explanation_cn":"让油狂喷向空中的井是 gusher(井喷)。✓ a well that lets oil spout wildly is a gusher. ✗ puddle 水坑;✗ fountain 喷泉;✗ drain 排水沟——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',6,NULL,'choice','{"stem":"derrick 的意思是:","options":["桥","井架,油井架","栅栏","梯子"],"answer_index":1,"explanation_cn":"derrick = 井架、油井架。✓ a tall steel tower, the derrick."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',6,NULL,'choice','{"stem":"strata 的意思是:","options":["云","河流","根","地层,岩层"],"answer_index":3,"explanation_cn":"strata = 地层、岩层(stratum 的复数)。✓ the strata the drill has been passing through."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',6,NULL,'choice','{"stem":"geologist 的意思是:","options":["画家","工程师","地质学家","生物学家"],"answer_index":2,"explanation_cn":"geologist = 地质学家。✓ once the geologists have decided where to drill."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',6,NULL,'choice','{"stem":"gusher 的意思是:","options":["水坑","水管","排水沟","井喷,喷油井"],"answer_index":3,"explanation_cn":"gusher = 井喷、喷油井。✓ the old, romantic gusher."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',6,NULL,'choice','{"stem":"haul 的意思是:","options":["抛","藏","拖,拽","买"],"answer_index":2,"explanation_cn":"haul = 拖、拽。✓ hauled out of the ground again."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',6,NULL,'choice','{"stem":"circulate 的意思是:","options":["使循环,流通","冻结","蒸发","停止"],"answer_index":0,"explanation_cn":"circulate = 使循环、流通。✓ the mud which the crew circulate down the pipe."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',7,NULL,'cloze','{"stem":"第 1 空","context":"Oil wells are the ___1___ holes of all. Once the geologists decide where to drill, a derrick ___2___ raised. A coring bit cuts a cylinder ___3___ which the strata can be read. We want the oil to stay down ___4___ it can be led off safely.","blank_no":1,"options":["deepest","deeper","deep","most deep"],"answer_index":0,"explanation_cn":"最高级 the deepest of all,‘最深的’。✓ Oil wells are the deepest holes of all."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',7,NULL,'cloze','{"stem":"第 2 空","context":"Oil wells are the ___1___ holes of all. Once the geologists decide where to drill, a derrick ___2___ raised. A coring bit cuts a cylinder ___3___ which the strata can be read. We want the oil to stay down ___4___ it can be led off safely.","blank_no":2,"options":["is","are","being","been"],"answer_index":0,"explanation_cn":"一般现在被动;derrick 单数用 is + 过去分词。✓ a derrick is raised."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',7,NULL,'cloze','{"stem":"第 3 空","context":"Oil wells are the ___1___ holes of all. Once the geologists decide where to drill, a derrick ___2___ raised. A coring bit cuts a cylinder ___3___ which the strata can be read. We want the oil to stay down ___4___ it can be led off safely.","blank_no":3,"options":["from","on","at","for"],"answer_index":0,"explanation_cn":"介词 + 关系代词:from which,‘从其中读出’。✓ a cylinder from which the strata can be read."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',7,NULL,'cloze','{"stem":"第 4 空","context":"Oil wells are the ___1___ holes of all. Once the geologists decide where to drill, a derrick ___2___ raised. A coring bit cuts a cylinder ___3___ which the strata can be read. We want the oil to stay down ___4___ it can be led off safely.","blank_no":4,"options":["until","since","although","whether"],"answer_index":0,"explanation_cn":"‘直到…才’引导时间从句,用 until。✓ stay down until it can be led off safely."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',8,NULL,'choice','{"stem":"What do the engineers want to happen as soon as they strike oil?","options":["To leave the well and move on","To keep it under control and prevent a wasteful gusher","To let it spout as high as possible","To burn it off at once"],"answer_index":1,"explanation_cn":"录音说工程师一采到油,就想把它牢牢控制住、防止白白浪费的井喷。✓ keep under control, prevent gusher."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',8,NULL,'choice','{"stem":"Why must an oil derrick be so tall?","options":["Because it hides the well","Because it stores the oil","Because it works like a giant block and tackle for the pipe","Because workers live inside it"],"answer_index":2,"explanation_cn":"录音说井架必须高,因为它像一套巨大的滑轮组,用来升降钻管。✓ like a giant block and tackle."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',8,NULL,'choice','{"stem":"How is a sample of the rock obtained?","options":["By washing it out with water","By sending men down the hole","By melting the rock","With a coring bit that cuts a clean cylinder of stone"],"answer_index":3,"explanation_cn":"录音说取样是用一枚取芯钻头,它切出一段干净的岩柱。✓ coring bit cuts a cylinder."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',9,NULL,'choice','{"stem":"你想说\"一座高高的井架被竖立在钻探地点上方\"(被动语态):","options":["A tall derrick is raise above the drilling spot.","A tall derrick is raised above the drilling spot.","A tall derrick raised above the drilling spot.","A tall derrick is being raise above the drilling spot."],"answer_index":1,"explanation_cn":"一般现在被动 is + 过去分词 raised;raise 须用过去分词 raised、不能少 is、不用进行 is being raise。✓ is raised. 场合:说“…被(竖立/做)”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',9,NULL,'choice','{"stem":"你想说\"地质学家一决定在哪钻,工作就开始\"(Once 从句):","options":["Once the geologists have decided where to drill, work begins.","Once the geologists have decided where to drill, work begin.","Once the geologists have decide where to drill, work begins.","Once the geologists has decided where to drill, work begins."],"answer_index":0,"explanation_cn":"Once ‘一…就’;从句 the geologists(复数)用 have decided、decide 须用过去分词 decided;主句 work 用 begins。✓ Once … have decided …, work begins. 场合:说“一…就…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',9,NULL,'choice','{"stem":"你想说\"工程师希望油留在井里,直到能安全引出\"(want sth to do + until):","options":["Engineers want the oil stay down the hole until it can be led off.","Engineers want the oil staying down the hole until it can be led off.","Engineers want the oil to stay down the hole until it can be led off.","Engineers want the oil to stays down the hole until it can be led off."],"answer_index":2,"explanation_cn":"want sth to do:want 后接不定式 to stay(不用原形 stay、不用 -ing staying、不用 to stays)。✓ want the oil to stay … until … 场合:说“希望…做…,直到…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',10,NULL,'choice','{"stem":"derrick 的意思是:","options":["桥","梯子","井架,油井架","栅栏"],"answer_index":2,"explanation_cn":"derrick = 井架、油井架。✓ a tall steel tower, the derrick."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',10,NULL,'choice','{"stem":"gusher 的意思是:","options":["水坑","井喷,喷油井","水管","排水沟"],"answer_index":1,"explanation_cn":"gusher = 井喷、喷油井。✓ the old, romantic gusher."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',10,NULL,'choice','{"stem":"\"A tall derrick ___ raised above the spot.\"(一般现在被动)","options":["are","being","been","is"],"answer_index":3,"stem_cn":"一座高高的井架被竖立在那地点之上。","explanation_cn":"一般现在被动;derrick 单数用 is + 过去分词。✓ A tall derrick is raised. ✗ are / being / been。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',10,NULL,'choice','{"stem":"\"___ the bit breaks into the oil, it rushes up.\"(‘一…就’,时间连词)","options":["Before","Once","Since","Though"],"answer_index":1,"stem_cn":"钻头一钻进油层,油就涌上来。","explanation_cn":"‘一…就’引导时间从句,用 Once。✓ Once the bit breaks into the oil, it rushes up. ✗ Since / Though / Before。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',10,NULL,'choice','{"stem":"\"by means of\" 的意思是:","options":["除非","尽管","借助、用…方法","为了"],"answer_index":2,"explanation_cn":"by means of = 借助、用…方法。✓ control it by means of heavy mud."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',10,NULL,'choice','{"stem":"\"break into\" 的意思是:","options":["分开","钻入、闯入","卖掉","修好"],"answer_index":1,"explanation_cn":"break into = 钻入、闯入。✓ the bit breaks into the oil."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',10,NULL,'choice','{"stem":"Why are oil holes never meant to carry men underground?","options":["They are only narrow borings, less than a foot across","They are made of glass","They are too short","They are full of water"],"answer_index":0,"passage":"Of all the holes that miners drill into the earth, those sunk in the search for oil are the deepest of all; some reach down as much as twenty-five thousand feet. Yet, unlike the shafts cut for coal or other mineral deposits, these holes are never meant to carry men underground. They are only narrow borings, less than a foot across, and it is largely the hunt for oil that has pushed the art of deep drilling further than any other kind of mining. Once the geologists have decided where to drill, a tall steel tower, the derrick, is raised above the spot. It has to stand high because it works like a giant block and tackle: from it, great lengths of pipe are lowered into the ground and later hauled out again. The pipe is rotated by a powerful engine at the top and is fitted at the bottom with a hard cutting bit that bites into the rock. Because the crew must know exactly which layers the drill has reached, a sample is now and then taken with a special coring bit, which cuts a clean cylinder of stone, from which the strata that the drill has been passing through can be clearly read. Once the bit breaks into the oil, the oil tends to rush up to the surface on its own, for it is driven by the great pressure of water or gas beneath it. That pressure must be kept firmly under control, and it is controlled by means of the heavy mud which the crew circulate down the pipe. Nobody today wants the old, romantic gusher that throws oil high into the air, since such a fountain only wastes oil and gas. The engineers want the oil to stay down the hole until it can be led off, quietly and safely, in a manner they choose.","explanation_cn":"课文说油孔只是不到一英尺宽的窄钻孔,从来不是要把人送下去的。✓ narrow borings, less than a foot."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',10,NULL,'choice','{"stem":"Why does nobody today want a gusher?","options":["It cannot reach the oil","It is too quiet","It wastes oil and gas by throwing them into the air","It is too cheap"],"answer_index":2,"passage":"Of all the holes that miners drill into the earth, those sunk in the search for oil are the deepest of all; some reach down as much as twenty-five thousand feet. Yet, unlike the shafts cut for coal or other mineral deposits, these holes are never meant to carry men underground. They are only narrow borings, less than a foot across, and it is largely the hunt for oil that has pushed the art of deep drilling further than any other kind of mining. Once the geologists have decided where to drill, a tall steel tower, the derrick, is raised above the spot. It has to stand high because it works like a giant block and tackle: from it, great lengths of pipe are lowered into the ground and later hauled out again. The pipe is rotated by a powerful engine at the top and is fitted at the bottom with a hard cutting bit that bites into the rock. Because the crew must know exactly which layers the drill has reached, a sample is now and then taken with a special coring bit, which cuts a clean cylinder of stone, from which the strata that the drill has been passing through can be clearly read. Once the bit breaks into the oil, the oil tends to rush up to the surface on its own, for it is driven by the great pressure of water or gas beneath it. That pressure must be kept firmly under control, and it is controlled by means of the heavy mud which the crew circulate down the pipe. Nobody today wants the old, romantic gusher that throws oil high into the air, since such a fountain only wastes oil and gas. The engineers want the oil to stay down the hole until it can be led off, quietly and safely, in a manner they choose.","explanation_cn":"课文说今天谁也不想要井喷,因为一柱冲天只会白白浪费油和气。✓ wastes oil and gas."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',10,NULL,'choice','{"stem":"What do the engineers want the oil to do when they strike it?","options":["Flow into the sea","Stay down the hole until it can be led off safely","Catch fire quickly","Spray as high as it can"],"answer_index":1,"audio":"Of all the holes that miners drill into the earth, those sunk in the search for oil are the deepest of all; some reach down as much as twenty-five thousand feet. Yet, unlike the shafts cut for coal or other mineral deposits, these holes are never meant to carry men underground. They are only narrow borings, less than a foot across, and it is largely the hunt for oil that has pushed the art of deep drilling further than any other kind of mining. Once the geologists have decided where to drill, a tall steel tower, the derrick, is raised above the spot. It has to stand high because it works like a giant block and tackle: from it, great lengths of pipe are lowered into the ground and later hauled out again. The pipe is rotated by a powerful engine at the top and is fitted at the bottom with a hard cutting bit that bites into the rock. Because the crew must know exactly which layers the drill has reached, a sample is now and then taken with a special coring bit, which cuts a clean cylinder of stone, from which the strata that the drill has been passing through can be clearly read. Once the bit breaks into the oil, the oil tends to rush up to the surface on its own, for it is driven by the great pressure of water or gas beneath it. That pressure must be kept firmly under control, and it is controlled by means of the heavy mud which the crew circulate down the pipe. Nobody today wants the old, romantic gusher that throws oil high into the air, since such a fountain only wastes oil and gas. The engineers want the oil to stay down the hole until it can be led off, quietly and safely, in a manner they choose.","explanation_cn":"课文说工程师希望油乖乖待在井里,直到能安全可控地引出。✓ stay down until led off safely."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l13',10,NULL,'choice','{"stem":"What is a coring bit used for?","options":["To light the derrick","To carry men down","To pump the oil out","To cut a clean cylinder of rock as a sample"],"answer_index":3,"audio":"Of all the holes that miners drill into the earth, those sunk in the search for oil are the deepest of all; some reach down as much as twenty-five thousand feet. Yet, unlike the shafts cut for coal or other mineral deposits, these holes are never meant to carry men underground. They are only narrow borings, less than a foot across, and it is largely the hunt for oil that has pushed the art of deep drilling further than any other kind of mining. Once the geologists have decided where to drill, a tall steel tower, the derrick, is raised above the spot. It has to stand high because it works like a giant block and tackle: from it, great lengths of pipe are lowered into the ground and later hauled out again. The pipe is rotated by a powerful engine at the top and is fitted at the bottom with a hard cutting bit that bites into the rock. Because the crew must know exactly which layers the drill has reached, a sample is now and then taken with a special coring bit, which cuts a clean cylinder of stone, from which the strata that the drill has been passing through can be clearly read. Once the bit breaks into the oil, the oil tends to rush up to the surface on its own, for it is driven by the great pressure of water or gas beneath it. That pressure must be kept firmly under control, and it is controlled by means of the heavy mud which the crew circulate down the pipe. Nobody today wants the old, romantic gusher that throws oil high into the air, since such a fountain only wastes oil and gas. The engineers want the oil to stay down the hole until it can be led off, quietly and safely, in a manner they choose.","explanation_cn":"课文说取芯钻头用来切出一段干净的岩柱作样本,好读出地层。✓ cut a cylinder as a sample."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l14',4,3,14,'The Butterfly Effect','蝴蝶效应','suppose + 虚拟(could be covered)+ 过去分词作定语(sensors placed one foot apart)、现在分词作状语(cascading upward)、将来完成时(will have created / will have spread)、定语从句(fluctuations that…)、whether/疑问词引导的从句(tell whether…/predict what…)(NCE4 无 KS 页,考点由课文结构自取;IP:源为詹姆斯·格雷克《混沌》名家科普,已用 100% 原创行文复述‘微小误差层层放大’的混沌概念,无逐句改写、无人物;题材=混沌理论与天气预测·无害;美语化 vapor/analyze;第四册第14课)','不管我们的仪器造得多好,天气永远跑在它前头。过了两三天,再精良的预报也变成臆测;过了一周,便与瞎猜相差无几。原因有个响亮的名字——蝴蝶效应。在任何一段流动的空气里,我们数字中最微小的误差都不会一直保持微小。它一点一点地把预测拖坏;那些小小的不确定性成倍增长,层层向上贯穿一整架躁动、湍急的运动,从在街角打转的小小涡流,一直升到宽如一个大陆的风暴系统。今天的天气模型建立在一张相隔数十英里的测量点网格之上;即便如此,大量起始数据仍只能靠猜,因为再密的观测站网也看不到每一寸天空。可是,假设整个星球能被每隔一英尺安放的传感器覆盖,以一英尺为步长一直排到大气层顶;假设每个传感器都报出完美的温度、气压和湿度读数——即便如此,一台功率无限的计算机也无法确切告诉你,某座城镇一个月后是晴还是雨。麻烦在于:传感器之间的缝隙仍会藏起无数波动——那是任何仪器都没能捕捉到的、对平均值的细微偏离。几分钟内,这些藏着的抖动便早已在一英尺开外孕育出小小的误差;再过一会儿,误差就会扩散到十英尺的尺度;错误就这样一步一步往上爬,直到把整个地球吞没。','{"q":"Listen and answer — Why do small errors make it impossible to predict the weather system with a high degree of accuracy?","options":["Because they multiply and cascade upward until they reach the size of the globe","Because computers are too slow","Because the weather never changes","Because sensors are banned"],"answer_index":0}'::jsonb,'{"title":"suppose+虚拟 / 现在分词状语 / 将来完成时 / 定语从句 / whether 从句","intro":"①suppose + 虚拟(could be covered);过去分词作定语:sensors placed one foot apart。②现在分词作状语:Errors multiply, cascading upward。③将来完成时 will have + 过去分词,表‘到将来某时之前早已…’:will have created。④定语从句:fluctuations that no instrument can catch。⑤whether/疑问词引导从句:cannot tell whether…；predict what will happen。","table":{"headers":["用法","结构","例子"],"rows":[["suppose+虚拟","suppose … could be done","suppose the earth could be covered"],["现在分词状语","…, doing …","Errors multiply, cascading upward"],["将来完成时","will have + 过去分词","will have created small errors"],["定语从句","名词 + that + 从句","fluctuations that no instrument can catch"],["whether 从句","tell/predict whether/what …","cannot tell whether it will rain"]]},"specialRules":[{"rule":"将来完成时 will have + 过去分词,表示到将来某个时间点之前动作已完成:By 12:01 … will already have created。","mark":"will have done"},{"rule":"suppose(假设)引导设想时,常配 could/would 等表示与现实拉开距离;过去分词作定语表被动:sensors placed apart。","mark":"suppose … could be done"},{"rule":"美式拼写:vapor(蒸汽,英式 vapour)、analyze(分析,英式 analyse)。本课已按美语写。","mark":"vapor / analyze"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l14',1,NULL,'No matter how good our instruments become, the weather will always outrun them. Past two or three days, even the finest forecast turns speculative; past a week, it is little better than a guess. The reason has a famous name — the butterfly effect.','不管我们的仪器造得多好,天气永远跑在它前头。过了两三天,再精良的预报也变成臆测;过了一周,便与瞎猜相差无几。原因有个响亮的名字——蝴蝶效应。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l14',2,NULL,'In any stretch of moving air, the smallest error in our numbers does not stay small. It deteriorates the prediction bit by bit; the little uncertainties multiply, cascading upward through a whole ladder of restless, turbulent motions, from the tiny eddies that spin at a street corner all the way up to storm systems as wide as a continent.','在任何一段流动的空气里,我们数字中最微小的误差都不会一直保持微小。它一点一点地把预测拖坏;那些小小的不确定性成倍增长,层层向上贯穿一整架躁动、湍急的运动,从在街角打转的小小涡流,一直升到宽如一个大陆的风暴系统。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l14',3,NULL,'Today''s weather models rest on a grid of measuring points spread dozens of miles apart, and even so a great deal of the starting data has to be guessed, since no network of stations can watch every acre of sky.','今天的天气模型建立在一张相隔数十英里的测量点网格之上;即便如此,大量起始数据仍只能靠猜,因为再密的观测站网也看不到每一寸天空。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l14',4,NULL,'But suppose the whole planet could be covered with sensors placed just one foot apart, reaching in one-foot steps clear to the top of the atmosphere. Suppose each sensor reported perfect readings of temperature, pressure, and humidity. Even then, a computer of unlimited power could not tell you for certain whether a given town would see sun or rain a month from now.','可是,假设整个星球能被每隔一英尺安放的传感器覆盖,以一英尺为步长一直排到大气层顶;假设每个传感器都报出完美的温度、气压和湿度读数——即便如此,一台功率无限的计算机也无法确切告诉你,某座城镇一个月后是晴还是雨。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l14',5,NULL,'The trouble is that the gaps between the sensors would still hide countless fluctuations — tiny deviations from the average that no instrument had caught. Within minutes those hidden wobbles will already have bred small errors a foot away; a little later the errors will have spread to the ten-foot scale, and so the mistake climbs, step by step, until it has swallowed the entire globe.','麻烦在于:传感器之间的缝隙仍会藏起无数波动——那是任何仪器都没能捕捉到的、对平均值的细微偏离。几分钟内,这些藏着的抖动便早已在一英尺开外孕育出小小的误差;再过一会儿,误差就会扩散到十英尺的尺度;错误就这样一步一步往上爬,直到把整个地球吞没。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
