INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l14','centimeter','centimetre','厘米;拼写差异,美语 -meter') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l14','modeling','modelling','建模;拼写差异,美语单 l') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l14','analyze','analyse','分析;拼写差异,美语 -yze') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l14','and so on','',NULL,'/ænd soʊ ɑːn/','The errors spread to ten feet, and so on up to the globe.','误差扩散到十英尺,如此一路直到全球。','We need pens, paper, and so on.','我们需要笔、纸等等。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l14','no matter how','',NULL,'/noʊ ˈmætər haʊ/','No matter how good the instruments are, the weather outruns them.','无论仪器多好,天气都跑在前头。','No matter how hard he tried, he failed.','无论他多努力,还是失败了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l14','a month from now','',NULL,'/ə mʌnθ frəm naʊ/','It cannot predict the weather a month from now.','它预测不出一个月后的天气。','I''ll graduate a year from now.','我一年后毕业。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l14','rest on','',NULL,'/rest ɑːn/','The models rest on a grid of points.','这些模型建立在一张点的网格上。','The theory rests on one assumption.','这一理论基于一个假设。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp1','choice','{"stem":"\"Suppose the earth ___ be covered with sensors one foot apart.\"(虚拟设想,‘能够’的过去式,填情态词)","options":["can","could","will","shall"],"answer_index":1,"stem_cn":"假设地球能布满每隔一英尺的传感器。","explanation_cn":"suppose 引导设想,常配 could 表示与现实拉开距离;‘能够’的过去式用 could。✓ Suppose the earth could be covered with sensors. ✗ can(不够虚拟)/ will / shall:此处用 could。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp1','choice','{"stem":"\"Suppose the planet could be ___ with tiny sensors.\"(被动 could be + 过去分词;cover 的过去分词)","options":["covering","cover","covered","to cover"],"answer_index":2,"stem_cn":"假设这颗行星能被细小的传感器覆盖。","explanation_cn":"被动 could be + 过去分词;cover 的过去分词 covered。✓ could be covered with sensors. ✗ covering(主动)/ cover / to cover:被动用过去分词 covered。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp1','choice','{"stem":"\"Sensors ___ one foot apart would still miss the gaps.\"(过去分词作定语,‘被安放的’;place 的过去分词)","options":["placed","to place","placing","place"],"answer_index":0,"stem_cn":"每隔一英尺安放的传感器仍会漏掉缝隙。","explanation_cn":"过去分词作定语,表被动“被安放的”;place 的过去分词 placed。✓ sensors placed one foot apart. ✗ placing(主动)/ place / to place:被动定语用过去分词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp2','choice','{"stem":"\"Small errors multiply, ___ upward through the whole system.\"(现在分词作状语,主动‘层层递升’)","options":["to cascade","cascading","cascade","cascaded"],"answer_index":1,"stem_cn":"小误差成倍增长,层层向上贯穿整个系统。","explanation_cn":"现在分词作状语,表主动“层层递升”。✓ Small errors multiply, cascading upward. ✗ cascaded(被动/过去)/ cascade / to cascade:主动伴随用 -ing。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp2','choice','{"stem":"\"The sensors rise in one-foot steps, ___ to the top of the sky.\"(现在分词作状语,主动‘一直延伸’)","options":["reached","reach","to reach","reaching"],"answer_index":3,"stem_cn":"传感器每隔一英尺升高,一直延伸到天顶。","explanation_cn":"现在分词作状语,表主动“一直延伸”。✓ The sensors rise …, reaching to the top of the sky. ✗ reached / reach / to reach:主动伴随用 -ing。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp2','choice','{"stem":"\"Storms grow, ___ from tiny eddies into vast systems.\"(现在分词作状语,主动‘发展成’)","options":["to spread","spread","spreading","spreads"],"answer_index":2,"stem_cn":"风暴不断壮大,由小小的涡流发展成庞大的天气系统。","explanation_cn":"现在分词作状语,表主动“发展/扩散成”。✓ Storms grow, spreading from tiny eddies into vast systems. ✗ spread / spreads / to spread:主动伴随用 -ing。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp3','choice','{"stem":"\"By 12:01, the wobbles ___ already have created small errors.\"(将来完成时:到某时刻之前‘早已…’,填该结构的第一个助动词)","options":["will","are","have","would"],"answer_index":0,"stem_cn":"到12点01分,那些扰动早已造出小误差。","explanation_cn":"将来完成时 will have + 过去分词;这一结构的第一个助动词是 will。✓ By 12:01, the wobbles will already have created errors. ✗ would / are / have:将来完成用 will have done。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp3','choice','{"stem":"\"Soon the errors will ___ multiplied to the ten-foot scale.\"(将来完成时 will ___ + 过去分词,填中间的助动词)","options":["be","has","have","had"],"answer_index":2,"stem_cn":"很快误差就会成倍扩大到十英尺尺度。","explanation_cn":"将来完成时 will have + 过去分词;中间的助动词是 have。✓ the errors will have multiplied. ✗ has / had / be:will 后一律用 have + 过去分词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp3','choice','{"stem":"\"In an hour the mistake ___ have spread across the region.\"(将来完成时,填第一个助动词)","options":["would","will","is","has"],"answer_index":1,"stem_cn":"一小时内,这个错误就会蔓延整个地区。","explanation_cn":"将来完成时 will have + 过去分词;第一个助动词是 will。✓ the mistake will have spread. ✗ would / is / has:将来完成用 will have done。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp4','choice','{"stem":"\"The gaps hide fluctuations ___ no instrument can catch.\"(定语从句,指物作宾语)","options":["what","who","that","whose"],"answer_index":2,"stem_cn":"那些缝隙藏着任何仪器都捕捉不到的波动。","explanation_cn":"定语从句先行词 fluctuations(物),关系词作宾语,用 that。✓ fluctuations that no instrument can catch. ✗ who(指人)/ what / whose:指物用 that。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp4','choice','{"stem":"\"The eddies ___ spin at a street corner are very small.\"(定语从句,指物作主语)","options":["that","who","whom","what"],"answer_index":0,"stem_cn":"在街角旋转的那些涡流很小。","explanation_cn":"定语从句先行词 eddies(物),关系词作主语,用 that。✓ the eddies that spin at a street corner. ✗ who / what / whom:指物作主语用 that。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp4','choice','{"stem":"\"Deviations ___ the computer never sees still change the result.\"(定语从句,指物作宾语)","options":["whose","what","who","that"],"answer_index":3,"stem_cn":"计算机从未察觉的偏差仍会改变结果。","explanation_cn":"定语从句先行词 deviations(物),关系词作宾语,用 that。✓ Deviations that the computer never sees. ✗ who / what / whose:指物用 that。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp5','choice','{"stem":"\"The computer cannot tell ___ a town will have sun or rain.\"(从句,‘是否’,填连词)","options":["whether","that","which","what"],"answer_index":0,"stem_cn":"计算机无法判断一座城镇是晴还是雨。","explanation_cn":"从句表“是否…”,用 whether。✓ cannot tell whether a town will have sun or rain. ✗ that / which / what:表“是否”用 whether。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp5','choice','{"stem":"\"No one can predict ___ will happen a month from now.\"(从句,‘什么’作主语,填连词)","options":["that","what","how","whether"],"answer_index":1,"stem_cn":"没人能预测一个月后会发生什么。","explanation_cn":"从句用 what,‘所…的事’在从句中作主语。✓ predict what will happen a month from now. ✗ that / whether / how:此处用 what。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp5','choice','{"stem":"\"Scientists study ___ small errors grow so fast.\"(从句,‘为什么’,填连词)","options":["that","if","whether","why"],"answer_index":3,"stem_cn":"科学家研究小误差为何长得这么快。","explanation_cn":"从句表“为什么”,用 why。✓ study why small errors grow so fast. ✗ that / whether / if:表“为什么”用 why。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp6','choice','{"stem":"\"Based on guessing, not solid fact, a claim is ___.\"(“推测的、臆测的”用哪个词)","options":["proven","speculative","exact","certain"],"answer_index":1,"stem_cn":"基于猜测而非确凿事实的。","explanation_cn":"基于猜测而非确凿事实的是 speculative(推测的)。✓ a claim based on guessing is speculative. ✗ certain 确定的;✗ proven 已证实的;✗ exact 精确的——都相反。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp6','choice','{"stem":"\"To grow worse in quality little by little is to ___.\"(“恶化、变差”用哪个词)","options":["deteriorate","improve","freeze","shine"],"answer_index":0,"stem_cn":"质量一点点变糟。","explanation_cn":"质量一点点变糟是 deteriorate(恶化)。✓ to grow worse is to deteriorate. ✗ improve 改善;✗ freeze 冻结;✗ shine 发光——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',5,'am4_l14_gp6','choice','{"stem":"\"The amount of water vapor in the air is ___.\"(“湿度”用哪个词)","options":["weight","humidity","distance","gravity"],"answer_index":1,"stem_cn":"空气中水汽的多少。","explanation_cn":"空气中水汽的多少是 humidity(湿度)。✓ the amount of water vapor is humidity. ✗ gravity 重力;✗ distance 距离;✗ weight 重量——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',6,NULL,'choice','{"stem":"forecast 的意思是:","options":["回忆","命令","预报,预测","道歉"],"answer_index":2,"explanation_cn":"forecast = 预报、预测。✓ even the finest forecast turns speculative."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',6,NULL,'choice','{"stem":"turbulent 的意思是:","options":["湍急的,动荡的","平静的","温暖的","干燥的"],"answer_index":0,"explanation_cn":"turbulent = 湍急的、动荡的。✓ restless, turbulent motions."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',6,NULL,'choice','{"stem":"multiply 的意思是:","options":["隐藏","停止","倍增,繁殖","减少"],"answer_index":2,"explanation_cn":"multiply = 倍增、繁殖。✓ the little uncertainties multiply."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',6,NULL,'choice','{"stem":"eddy 的意思是:","options":["涡流,旋涡","桥梁","沙漠","山峰"],"answer_index":0,"explanation_cn":"eddy = 涡流、旋涡。✓ the tiny eddies that spin at a corner."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',6,NULL,'choice','{"stem":"deviation 的意思是:","options":["平均","总和","中心","偏差,偏离"],"answer_index":3,"explanation_cn":"deviation = 偏差、偏离。✓ tiny deviations from the average."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',6,NULL,'choice','{"stem":"sensor 的意思是:","options":["电池","屏幕","传感器,感应器","开关"],"answer_index":2,"explanation_cn":"sensor = 传感器、感应器。✓ covered with sensors one foot apart."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',7,NULL,'cloze','{"stem":"第 1 空","context":"Beyond a few days, the best forecast turns ___1___. Small errors multiply, ___2___ upward through the whole system. Suppose the earth ___3___ be covered with perfect sensors; even then no computer could predict ___4___ a town will have sun or rain.","blank_no":1,"options":["speculative","certain","proven","exact"],"answer_index":0,"explanation_cn":"speculative = 推测的、臆测的。✓ the best forecast turns speculative."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',7,NULL,'cloze','{"stem":"第 2 空","context":"Beyond a few days, the best forecast turns ___1___. Small errors multiply, ___2___ upward through the whole system. Suppose the earth ___3___ be covered with perfect sensors; even then no computer could predict ___4___ a town will have sun or rain.","blank_no":2,"options":["cascading","cascaded","cascade","to cascade"],"answer_index":0,"explanation_cn":"现在分词作状语,主动“层层递升”。✓ Small errors multiply, cascading upward."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',7,NULL,'cloze','{"stem":"第 3 空","context":"Beyond a few days, the best forecast turns ___1___. Small errors multiply, ___2___ upward through the whole system. Suppose the earth ___3___ be covered with perfect sensors; even then no computer could predict ___4___ a town will have sun or rain.","blank_no":3,"options":["could","can","will","shall"],"answer_index":0,"explanation_cn":"suppose 引导设想配 could;‘能够’的过去式用 could。✓ Suppose the earth could be covered."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',7,NULL,'cloze','{"stem":"第 4 空","context":"Beyond a few days, the best forecast turns ___1___. Small errors multiply, ___2___ upward through the whole system. Suppose the earth ___3___ be covered with perfect sensors; even then no computer could predict ___4___ a town will have sun or rain.","blank_no":4,"options":["whether","that","which","how"],"answer_index":0,"explanation_cn":"从句表“是否”,用 whether。✓ predict whether a town will have sun or rain."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',8,NULL,'choice','{"stem":"Why do small errors make accurate weather prediction impossible?","options":["They only affect one town","They are easy to remove","They multiply and cascade upward until they reach the size of the globe","They freeze the computer"],"answer_index":2,"explanation_cn":"录音说微小误差会成倍增长、层层向上放大,一直扩大到全球尺度,故无法精确预测。✓ multiply and cascade up to the globe."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',8,NULL,'choice','{"stem":"What would still defeat a perfect network of sensors one foot apart?","options":["The size of the computer","The fluctuations hidden in the gaps between them","A power cut","Too much sunshine"],"answer_index":1,"explanation_cn":"录音说即便传感器每隔一英尺,它们之间的缝隙仍藏着无数波动,足以毁掉预测。✓ hidden fluctuations in the gaps."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',8,NULL,'choice','{"stem":"Beyond how long does the best forecast become worthless?","options":["Beyond about six or seven days","Beyond one year","It never does","Beyond one hour"],"answer_index":0,"explanation_cn":"录音说过了六七天,再好的预报也变得毫无价值。✓ beyond six or seven days."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',9,NULL,'choice','{"stem":"你想说\"假设地球能布满每隔一英尺的传感器\"(suppose + 被动虚拟):","options":["Suppose the earth could be covering with sensors one foot apart.","Suppose the earth could be cover with sensors one foot apart.","Suppose the earth could be covered with sensors one foot apart.","Suppose the earth could covered with sensors one foot apart."],"answer_index":2,"explanation_cn":"suppose + 被动虚拟 could be covered;cover 须用过去分词 covered、不能少 be、不用主动 covering。✓ could be covered. 场合:说“假设…能被…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',9,NULL,'choice','{"stem":"你想说\"到12点01分,那些扰动早已造出小误差\"(将来完成时):","options":["By 12:01, those wobbles will already have create small errors.","By 12:01, those wobbles will already have created small errors.","By 12:01, those wobbles will already created small errors.","By 12:01, those wobbles already have created small errors."],"answer_index":1,"explanation_cn":"将来完成时 will have + 过去分词;不能少 will、不能少 have、create 须用过去分词 created。✓ will already have created. 场合:说“到将来某时,早已…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',9,NULL,'choice','{"stem":"你想说\"计算机无法判断一座城镇是晴还是雨\"(whether‘是否’引导的从句):","options":["The computer cannot tell whether will a town have sun or rain.","The computer cannot tell whether a town will has sun or rain.","The computer cannot tell that a town will have sun or rain.","The computer cannot tell whether a town will have sun or rain."],"answer_index":3,"explanation_cn":"从句用 whether‘是否’引导;不用 that、从句用陈述语序(不倒装 will a town)、have 用原形。✓ tell whether a town will have… 场合:说“说不准是否…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',10,NULL,'choice','{"stem":"forecast 的意思是:","options":["命令","道歉","预报,预测","回忆"],"answer_index":2,"explanation_cn":"forecast = 预报、预测。✓ the finest forecast turns speculative."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',10,NULL,'choice','{"stem":"deviation 的意思是:","options":["总和","偏差,偏离","平均","中心"],"answer_index":1,"explanation_cn":"deviation = 偏差、偏离。✓ tiny deviations from the average."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',10,NULL,'choice','{"stem":"\"Suppose the earth ___ be covered with sensors.\"(虚拟设想,‘能够’的过去式)","options":["could","will","can","shall"],"answer_index":0,"stem_cn":"假设地球能被传感器覆盖。","explanation_cn":"suppose 引导设想配 could;‘能够’的过去式用 could。✓ Suppose the earth could be covered. ✗ can / will / shall。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',10,NULL,'choice','{"stem":"\"Small errors multiply, ___ upward through the system.\"(现在分词作状语)","options":["to cascade","cascading","cascade","cascaded"],"answer_index":1,"stem_cn":"小误差成倍增长,层层向上贯穿系统。","explanation_cn":"现在分词作状语,主动“层层递升”。✓ Small errors multiply, cascading upward. ✗ cascaded / cascade / to cascade。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',10,NULL,'choice','{"stem":"\"and so on\" 的意思是:","options":["完全地","立刻","等等、诸如此类","从此以后"],"answer_index":2,"explanation_cn":"and so on = 等等、诸如此类。✓ ten feet, and so on up to the globe."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',10,NULL,'choice','{"stem":"\"no matter how\" 的意思是:","options":["因为","无论多么…","除非","只要"],"answer_index":1,"explanation_cn":"no matter how = 无论多么…。✓ no matter how good the instruments are."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',10,NULL,'choice','{"stem":"According to the passage, what happens to a tiny error in the numbers?","options":["It stays exactly the same size","It only cools the air","It multiplies and climbs step by step up to the size of the globe","It disappears within minutes"],"answer_index":2,"passage":"No matter how good our instruments become, the weather will always outrun them. Past two or three days, even the finest forecast turns speculative; past a week, it is little better than a guess. The reason has a famous name — the butterfly effect. In any stretch of moving air, the smallest error in our numbers does not stay small. It deteriorates the prediction bit by bit; the little uncertainties multiply, cascading upward through a whole ladder of restless, turbulent motions, from the tiny eddies that spin at a street corner all the way up to storm systems as wide as a continent. Today''s weather models rest on a grid of measuring points spread dozens of miles apart, and even so a great deal of the starting data has to be guessed, since no network of stations can watch every acre of sky. But suppose the whole planet could be covered with sensors placed just one foot apart, reaching in one-foot steps clear to the top of the atmosphere. Suppose each sensor reported perfect readings of temperature, pressure, and humidity. Even then, a computer of unlimited power could not tell you for certain whether a given town would see sun or rain a month from now. The trouble is that the gaps between the sensors would still hide countless fluctuations — tiny deviations from the average that no instrument had caught. Within minutes those hidden wobbles will already have bred small errors a foot away; a little later the errors will have spread to the ten-foot scale, and so the mistake climbs, step by step, until it has swallowed the entire globe.","explanation_cn":"课文说数字里最微小的误差不会一直小,它成倍增长、一步步往上爬,直到吞没整个地球。✓ multiplies and climbs up to the globe."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',10,NULL,'choice','{"stem":"Why can''t even perfect sensors one foot apart give a sure month-ahead forecast?","options":["The sensors are too expensive","The computer is too slow","The air is too still","The gaps between them still hide countless fluctuations"],"answer_index":3,"passage":"No matter how good our instruments become, the weather will always outrun them. Past two or three days, even the finest forecast turns speculative; past a week, it is little better than a guess. The reason has a famous name — the butterfly effect. In any stretch of moving air, the smallest error in our numbers does not stay small. It deteriorates the prediction bit by bit; the little uncertainties multiply, cascading upward through a whole ladder of restless, turbulent motions, from the tiny eddies that spin at a street corner all the way up to storm systems as wide as a continent. Today''s weather models rest on a grid of measuring points spread dozens of miles apart, and even so a great deal of the starting data has to be guessed, since no network of stations can watch every acre of sky. But suppose the whole planet could be covered with sensors placed just one foot apart, reaching in one-foot steps clear to the top of the atmosphere. Suppose each sensor reported perfect readings of temperature, pressure, and humidity. Even then, a computer of unlimited power could not tell you for certain whether a given town would see sun or rain a month from now. The trouble is that the gaps between the sensors would still hide countless fluctuations — tiny deviations from the average that no instrument had caught. Within minutes those hidden wobbles will already have bred small errors a foot away; a little later the errors will have spread to the ten-foot scale, and so the mistake climbs, step by step, until it has swallowed the entire globe.","explanation_cn":"课文说即使传感器每隔一英尺,它们之间的缝隙仍藏着无数波动,所以仍无法给出确切预报。✓ gaps hide countless fluctuations."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',10,NULL,'choice','{"stem":"What is the famous name for the reason small errors ruin forecasts?","options":["The butterfly effect","The ripple test","The snowball law","The domino rule"],"answer_index":0,"audio":"No matter how good our instruments become, the weather will always outrun them. Past two or three days, even the finest forecast turns speculative; past a week, it is little better than a guess. The reason has a famous name — the butterfly effect. In any stretch of moving air, the smallest error in our numbers does not stay small. It deteriorates the prediction bit by bit; the little uncertainties multiply, cascading upward through a whole ladder of restless, turbulent motions, from the tiny eddies that spin at a street corner all the way up to storm systems as wide as a continent. Today''s weather models rest on a grid of measuring points spread dozens of miles apart, and even so a great deal of the starting data has to be guessed, since no network of stations can watch every acre of sky. But suppose the whole planet could be covered with sensors placed just one foot apart, reaching in one-foot steps clear to the top of the atmosphere. Suppose each sensor reported perfect readings of temperature, pressure, and humidity. Even then, a computer of unlimited power could not tell you for certain whether a given town would see sun or rain a month from now. The trouble is that the gaps between the sensors would still hide countless fluctuations — tiny deviations from the average that no instrument had caught. Within minutes those hidden wobbles will already have bred small errors a foot away; a little later the errors will have spread to the ten-foot scale, and so the mistake climbs, step by step, until it has swallowed the entire globe.","explanation_cn":"课文说微小误差毁掉预报的原因有个响亮的名字——蝴蝶效应。✓ the butterfly effect."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l14',10,NULL,'choice','{"stem":"Beyond how many days does the best forecast become little better than a guess?","options":["Beyond a year","Beyond about a week","Beyond an hour","Beyond a month"],"answer_index":1,"audio":"No matter how good our instruments become, the weather will always outrun them. Past two or three days, even the finest forecast turns speculative; past a week, it is little better than a guess. The reason has a famous name — the butterfly effect. In any stretch of moving air, the smallest error in our numbers does not stay small. It deteriorates the prediction bit by bit; the little uncertainties multiply, cascading upward through a whole ladder of restless, turbulent motions, from the tiny eddies that spin at a street corner all the way up to storm systems as wide as a continent. Today''s weather models rest on a grid of measuring points spread dozens of miles apart, and even so a great deal of the starting data has to be guessed, since no network of stations can watch every acre of sky. But suppose the whole planet could be covered with sensors placed just one foot apart, reaching in one-foot steps clear to the top of the atmosphere. Suppose each sensor reported perfect readings of temperature, pressure, and humidity. Even then, a computer of unlimited power could not tell you for certain whether a given town would see sun or rain a month from now. The trouble is that the gaps between the sensors would still hide countless fluctuations — tiny deviations from the average that no instrument had caught. Within minutes those hidden wobbles will already have bred small errors a foot away; a little later the errors will have spread to the ten-foot scale, and so the mistake climbs, step by step, until it has swallowed the entire globe.","explanation_cn":"课文说过了一周,再好的预报也不过比瞎猜强一点。✓ beyond about a week."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
